mkdir -p apps/web/app/api/v3/account/data-export/lib && cat > apps/web/app/api/v3/account/data-export/lib/operations.ts <<'EOF'
import "server-only";
import { prisma } from "@formbricks/database";
import { problemInternalError, problemUnauthorized, successResponse } from "@/app/api/v3/lib/response";
import { getV3SessionUserId } from "@/app/api/v3/lib/auth";
import type { TV3Authentication } from "@/app/api/v3/lib/types";

export type TV3AccountDataExport = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: unknown;
  memberships: { organizationName: string; role: string }[];
};

export async function getV3AccountDataExport(params: {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
}): Promise<Response> {
  const { authentication, requestId, instance } = params;

  // The subject is always the signed-in user; there is deliberately no id in the request.
  const userId = getV3SessionUserId(authentication);
  if (!userId) return problemUnauthorized(requestId, "Session required", instance);

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      name: true,
      email: true,
      locale: true,
      notificationSettings: true,
      memberships: {
        where: { accepted: true },
        select: { role: true, organization: { select: { name: true } } },
      },
    },
  });
  if (!user) return problemInternalError(requestId, "Unable to export account data", instance);

  const data: TV3AccountDataExport = {
    name: user.name,
    email: user.email,
    locale: user.locale,
    notificationSettings: user.notificationSettings,
    memberships: user.memberships.map((membership) => ({
      organizationName: membership.organization.name,
      role: membership.role,
    })),
  };

  return successResponse(data, { requestId });
}
EOF
cat > apps/web/app/api/v3/account/data-export/route.ts <<'EOF'
/**
 * GET /api/v3/account/data-export - the signed-in user's own personal data.
 *
 * Session-only, deliberately: it exports the account behind the session and takes no identifier, so an
 * API key (which has no user) has nothing to export.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { getV3AccountDataExport } from "./lib/operations";

export const GET = withV3ApiWrapper({
  auth: "session",
  handler: async ({ authentication, requestId, instance }) =>
    getV3AccountDataExport({ authentication, requestId, instance }),
});
EOF
cat > docs/api-v3-reference/src/paths/api_v3_account_data-export.yml <<'EOF'
get:
  operationId: getAccountDataExportV3
  # Session-only, like the tags operations: the Formbricks app calls it from the profile page.
  x-excluded: true
  summary: Export my account data
  description: |
    Returns the signed-in user's name, email, locale, notification settings and organization memberships
    (organization name and role).

    Session cookie only. The endpoint takes no identifier and always exports the account behind the session.
  tags:
    - V3 Account
  responses:
    "200":
      description: Account data retrieved successfully
      headers:
        X-Request-Id:
          schema:
            type: string
          description: Request correlation ID
        Cache-Control:
          schema:
            type: string
          example: private, no-store
      content:
        application/json:
          schema:
            type: object
            required:
              - data
            properties:
              data:
                type: object
                required:
                  - name
                  - email
                  - locale
                  - notificationSettings
                  - memberships
                properties:
                  name:
                    type: string
                  email:
                    type: string
                  locale:
                    type: string
                  notificationSettings:
                    type: object
                    additionalProperties: true
                  memberships:
                    type: array
                    items:
                      type: object
                      required:
                        - organizationName
                        - role
                      properties:
                        organizationName:
                          type: string
                        role:
                          type: string
    "401":
      $ref: ../components/responses/V3UnauthorizedSession.yml
    "429":
      $ref: ../components/responses/V3TooManyRequests.yml
    "500":
      $ref: ../components/responses/V3InternalServerError.yml
  security:
    - sessionAuth: []
EOF
python3 - <<'EOF'
p='docs/api-v3-reference/src/openapi.yml'
s=open(p).read()
s=s.replace("  /api/v3/tags:\n","  /api/v3/account/data-export:\n    $ref: paths/api_v3_account_data-export.yml\n  /api/v3/tags:\n",1)
open(p,'w').write(s)
EOF
